import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.BTt0kA_k.js";const i="/RelayPulse/screenshots/user/question-edit.webp",_=JSON.parse('{"title":"题库管理","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/questions.md","filePath":"user/use/questions.md"}'),o={name:"user/use/questions.md"};function n(l,e,u,p,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="题库管理" tabindex="-1">题库管理 <a class="header-anchor" href="#题库管理" aria-label="Permalink to &quot;题库管理&quot;">​</a></h1><p>入口：<strong>测试 → 题库管理</strong>。在这里维护智商测试使用的题目及参考答案。</p><h2 id="新增题目" tabindex="-1">新增题目 <a class="header-anchor" href="#新增题目" aria-label="Permalink to &quot;新增题目&quot;">​</a></h2><ol><li>点击“新建题目”（空题库时为“新建第一道题目”），打开题目编辑抽屉。</li><li>在“题目”中填写要发给模型的完整问题。</li><li>按需填写“参考答案（选填）”，用于之后人工比较回答。</li><li>点击“保存”，在列表确认题目及启用状态。</li></ol><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/question-edit.webp"><img src="'+i+'" alt="新建题目抽屉，填写算术题面和可选参考答案"></a></p><figcaption>① 发给模型的题目；② 供人工比较的参考答案。参考答案不会作为模型回答正确与否的自动判定。</figcaption></figure><p>题面不能为空，最长 <strong>4096 个字符</strong>；参考答案选填，最长 <strong>4096 个字符</strong>。保存前后会去除首尾空白。</p><p>建议一条题目只描述一个明确任务，包含必要背景和输出要求；需要比较多个模型时，使用相同题面，便于阅读差异。</p><h2 id="查找和查看题目" tabindex="-1">查找和查看题目 <a class="header-anchor" href="#查找和查看题目" aria-label="Permalink to &quot;查找和查看题目&quot;">​</a></h2><p>可以搜索题目内容，并按“全部题目”“已启用”“已停用”筛选。点击题目可查看全文与参考答案；使用编辑图标修改内容。</p><p>保存失败时，抽屉会保留本次输入；阅读错误提示，修正后再次保存。</p><h2 id="启用、停用与删除" tabindex="-1">启用、停用与删除 <a class="header-anchor" href="#启用、停用与删除" aria-label="Permalink to &quot;启用、停用与删除&quot;">​</a></h2><ul><li><strong>启用</strong>：允许在智商测试中选择该题目。</li><li><strong>停用</strong>：保留题目，但不参与新的题目选择。</li><li><strong>删除</strong>：从当前题库移除，需在确认框中确认。</li></ul><p>历史运行保存独立的题目快照。编辑、停用或删除当前题目，不会改写已经保存的历史题面与参考答案。</p><p>题目保存后，进入<a href="./iq-test.html">智商测试</a>选择要运行的题目。</p>',14)])])}const g=t(o,[["render",n]]);export{_ as __pageData,g as default};
